// ResourceConfigV030 is a migration wrapper around the otelconf v0.3.0
// config.Resource type. It adds support for the legacy inline resource
// attribute format, where resource attributes were specified as an inline
// map of string keys to (possibly nil) string values.
//
// The embedded config.Resource is squashed, so its fields (attributes,
// schema_url, detectors, attributes_list) are promoted. Any keys that do
// not correspond to a known config.Resource field are captured in
// LegacyAttributes via the mapstructure "remain" tag.
type ResourceConfigV030 struct {
	// Resource holds the declarative resource configuration. Its fields
	// (Attributes, SchemaUrl, Detectors, AttributesList) are promoted.
	config.Resource `mapstructure:",squash"`

	// LegacyAttributes captures resource attributes specified using the
	// legacy inline map format. Keys explicitly set to nil (which suppress
	// the corresponding default attribute) are NOT stored here.
	LegacyAttributes map[string]any `mapstructure:",remain"`
}

func (r *ResourceConfigV030) Unmarshal(conf *confmap.Conf) error {
	if err := conf.Unmarshal(r); err != nil {
		return err
	}
	// Nil-valued legacy keys must not be stored in the LegacyAttributes map.
	// A nil value indicates that the corresponding default attribute should
	// be removed from the resource; this is handled elsewhere.
	for k, v := range r.LegacyAttributes {
		if v == nil {
			delete(r.LegacyAttributes, k)
		}
	}
	if len(r.LegacyAttributes) == 0 {
		r.LegacyAttributes = nil
	}
	return nil
}

func (r *ResourceConfigV030) Validate() error {
	if r.AttributesList != nil {
		return errors.New("resource::attributes_list is not currently supported")
	}
	if len(r.Attributes) > 0 && len(r.LegacyAttributes) > 0 {
		return errors.New("resource::attributes cannot be used together with legacy inline resource attributes")
	}
	for name, value := range r.LegacyAttributes {
		if value == nil {
			continue
		}
		if _, ok := value.(string); !ok {
			return fmt.Errorf("resource::%s: legacy inline resource attribute values must be strings, got %T", name, value)
		}
	}
	return nil
}
