// errMissingCollectorResource is returned by the telemetry provider
// constructors when the settings do not contain a resource.
var errMissingCollectorResource = errors.New("missing collector resource")

// defaultAttributeValues returns the default resource attribute values for the
// given build info. It is a variable so that it can be replaced in tests.
var defaultAttributeValues = func(buildInfo component.BuildInfo) (map[string]string, error) {
	instanceUUID, err := uuid.NewRandom()
	if err != nil {
		return nil, err
	}
	return map[string]string{
		string(semconv.ServiceNameKey):       buildInfo.Command,
		string(semconv.ServiceVersionKey):    buildInfo.Version,
		string(semconv.ServiceInstanceIDKey): instanceUUID.String(),
	}, nil
}

// createResource creates a pcommon.Resource from the given settings and Config.
//
// A new, independent pcommon.Resource is created for each call. Resources are
// never cached or shared across invocations.
func createResource(
	_ context.Context,
	set telemetry.Settings,
	componentConfig component.Config,
) (pcommon.Resource, error) {
	cfg := componentConfig.(*Config)
	resourceConfig, err := createInitialResourceConfig(set.BuildInfo, &cfg.Resource)
	if err != nil {
		return pcommon.Resource{}, err
	}
	res := pcommon.NewResource()
	for _, attr := range resourceConfig.Attributes {
		putAttributeValue(res.Attributes(), attr.Name, attr.Value)
	}
	return res, nil
}

// createInitialResourceConfig creates an otelconf *config.Resource by combining
// the default attribute values with the resource configuration. Attribute names
// that were set to nil in the legacy inline format are excluded, so that the
// corresponding default attributes are removed from the resource.
func createInitialResourceConfig(buildInfo component.BuildInfo, cfg *migration.ResourceConfigV030) (*config.Resource, error) {
	defaults, err := defaultAttributeValues(buildInfo)
	if err != nil {
		return nil, err
	}

	res := &config.Resource{
		SchemaUrl: schemaURL(cfg.SchemaUrl),
		Detectors: cfg.Detectors,
	}

	// Add default attributes, excluding any that are set (as keys) in the
	// legacy inline format. Legacy keys with a nil value suppress the default;
	// legacy keys with a string value override it (appended below).
	for name, value := range defaults {
		if _, ok := cfg.LegacyAttributes[name]; ok {
			continue
		}
		res.Attributes = append(res.Attributes, config.AttributeNameValue{Name: name, Value: value})
	}

	// Append non-nil legacy attributes.
	for name, value := range cfg.LegacyAttributes {
		if value == nil {
			continue
		}
		res.Attributes = append(res.Attributes, config.AttributeNameValue{Name: name, Value: value})
	}

	// Append declarative attributes.
	res.Attributes = append(res.Attributes, cfg.Attributes...)

	return res, nil
}

// createFixedResourceConfig converts an already-resolved pcommon.Resource into
// an otelconf *config.Resource, copying the SchemaUrl from the config and
// converting all resource attributes to config.AttributeNameValue entries.
func createFixedResourceConfig(cfg *migration.ResourceConfigV030, res *pcommon.Resource) (*config.Resource, error) {
	if res == nil {
		return nil, errMissingCollectorResource
	}
	out := &config.Resource{
		SchemaUrl: schemaURL(cfg.SchemaUrl),
		Detectors: cfg.Detectors,
	}
	out.Attributes = make([]config.AttributeNameValue, 0, res.Attributes().Len())
	res.Attributes().Range(func(k string, v pcommon.Value) bool {
		out.Attributes = append(out.Attributes, config.AttributeNameValue{Name: k, Value: v.AsRaw()})
		return true
	})
	return out, nil
}

// schemaURL returns the configured schema URL, or the default semconv schema
// URL if none is configured.
func schemaURL(configured *string) *string {
	if configured != nil {
		return configured
	}
	return ptr(semconv.SchemaURL)
}

// putAttributeValue stores the given value in the map using the same type
// conversion rules as the otelconf SDK (see go.opentelemetry.io/contrib/otelconf
// internal kv.FromNameValue).
func putAttributeValue(m pcommon.Map, k string, v any) {
	switch val := v.(type) {
	case bool:
		m.PutBool(k, val)
	case int:
		m.PutInt(k, int64(val))
	case int8:
		m.PutInt(k, int64(val))
	case int16:
		m.PutInt(k, int64(val))
	case int32:
		m.PutInt(k, int64(val))
	case int64:
		m.PutInt(k, val)
	case uint8:
		m.PutInt(k, int64(val))
	case uint16:
		m.PutInt(k, int64(val))
	case uint32:
		m.PutInt(k, int64(val))
	case uint:
		m.PutStr(k, strconv.FormatUint(uint64(val), 10))
	case uint64:
		m.PutStr(k, strconv.FormatUint(val, 10))
	case float32:
		m.PutDouble(k, float64(val))
	case float64:
		m.PutDouble(k, val)
	case string:
		m.PutStr(k, val)
	default:
		m.PutStr(k, fmt.Sprint(v))
	}
}

func attributeValueString(k string, v attribute.Value) (string, error) {
	if v.Type() != attribute.STRING {
		// We only support string-type resource attributes in the configuration.
		return "", fmt.Errorf("attribute %q: expected string, got %s", k, v.Type())
	}
	return v.AsString(), nil
}

// pcommonAttrsToOTelAttrs gets the Resource attributes to OpenTelemetry attribute.KeyValue slice.
func pcommonAttrsToOTelAttrs(resource *pcommon.Resource) []attribute.KeyValue {
	var result []attribute.KeyValue
	if resource != nil {
		attrs := resource.Attributes()
		attrs.Range(func(k string, v pcommon.Value) bool {
			result = append(result, attribute.String(k, v.AsString()))
			return true
		})
	}
	return result
}
